/***
*  ts_weapons.cpp — RECONSTRUCTED TS weapon data table (get_weapon_info).
*  Functional/source-faithful (see CLAUDE.md).
*
*  The original builds a 38-entry table via compile_weapons_info() (@0x6fe28)
*  calling Write_<weapon>(&table[i]). We do the same with a clean s_weapon_info.
*  The table below is generated by scripts/extract_weapons.py straight from the
*  Write_<weapon> functions (name/models/anim-ext/fire/clip/damage/fire-type).
*  Index 29 (flag, a CTF objective) is not in compile_weapons_info -> left blank.
***/
#include "extdll.h"
#include "util.h"
#include "cbase.h"
#include "ts_weapons.h"

static s_weapon_info g_weaponInfo[TSW_COUNT];
static bool g_weaponInfoCompiled = false;

static void Write(s_weapon_info *w, const char *name, const char *v, const char *p,
	const char *world, const char *anim, const char *fire, int clip, float dmg, int firetype,
	float rate, float spread, float recoil)
{
	w->pszName = name;
	w->pszViewModel = v;
	w->pszPlayerModel = p;
	w->pszWorldModel = world;
	w->pszAnimExt = anim ? anim : "onehanded";
	w->pszFireSound = fire;
	w->iClip = clip;
	w->flDamage = dmg;
	w->iFireType = firetype;
	w->flFireRate = rate;
	w->flSpread = spread;
	w->flRecoil = recoil;
	w->iAkimboType = -1; // default: no akimbo upgrade (set in compile_weapons_info)
	w->iSingleType = -1;
	w->iFireModes = 2;   // default: semi only (overridden in compile_weapons_info)
	w->iCaliber = 0;     // default: no caliber (overridden in compile_weapons_info)
	w->iPellets = 1;     // default: one bullet (overridden in compile_weapons_info)
	w->iFireAnim = -1;   // default: no standard fire anim (overridden in compile_weapons_info)
	w->iFireAnimL = -1;  // default: not akimbo (overridden in compile_weapons_info)
	w->iReloadAnim = -1; // default: no reload anim (overridden in compile_weapons_info)
}

// Max per-caliber reserve (rounds), s_ammo_info+0x20 from compile_ammo_info (@0x6f51c).
// Index = caliber. 0 = none. Calibers: 1 9x19, 2 .45, 3 SHELLS, 4 5.56, 5 .50AE, 6 7.62,
// 7 5.7, 8 50BMG, 9 10mm, 10 .22, 11 .454, 12 .32, 13 .45LC.
static const int kAmmoMax[TS_NUM_CALIBERS] = {
	0, 80, 90, 90, 150, 90, 170, 100, 200, 90, 70, 20, 40, 170, 0, 0,
};

int TSAmmoMax(int caliber)
{
	if (caliber < 0 || caliber >= TS_NUM_CALIBERS)
		return 0;
	return kAmmoMax[caliber];
}

// Rounds per magazine per caliber, s_ammo_info+0x10 from compile_ammo_info (@0x6f51c).
// Used by CTSGroundAmmo: a `magsN` keyvalue gives magcount * roundsPerMag rounds of caliber N
// (recovered: CTSGroundAmmo::KeyValue stores magcount * get_ammo_info(N)[+0x10]). Index=caliber.
static const int kRoundsPerMag[TS_NUM_CALIBERS] = {
	0, 30, 12, 8, 30, 10, 30, 20, 5, 15, 17, 5, 20, 5, 0, 0,
};

int TSRoundsPerMag(int caliber)
{
	if (caliber < 0 || caliber >= TS_NUM_CALIBERS)
		return 0;
	return kRoundsPerMag[caliber];
}

// @ TakeWeapon default-mode selection — auto if offered, else pump, else burst, else semi.
int TSDefaultFireMode(int modeMask)
{
	if (modeMask & (1 << TSFM_AUTO))  return TSFM_AUTO;
	if (modeMask & (1 << TSFM_PUMP))  return TSFM_PUMP;
	if (modeMask & (1 << TSFM_BURST)) return TSFM_BURST;
	return TSFM_SEMI;
}

